using System.Collections.Generic;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CurrentActiveUnits", menuName = "Data/Battle/Current Active Units")]
public class CurrentActiveUnits : ScriptableObject
{
	[Header("Units")]
	[SerializeField]
	private CurrentCompanions currentCompanions;

	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private GameObjectReference playerGameObjectReference;

	public CurrentCompanions CurrentCompanions => currentCompanions;

	public CurrentCorruptedAnimals CurrentCorruptedAnimals => currentCorruptedAnimals;

	public GameObject PlayerGameObject => playerGameObjectReference.value;

	public List<GameObject> GetCurrentActiveUnits()
	{
		List<GameObject> list = new List<GameObject>();
		list.AddRange(currentCompanions.ActiveCompanions);
		list.Add(ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject);
		list.AddRange(currentCorruptedAnimals.activeCorruptedAnimals);
		return list;
	}

	public int IsHypersensitiveAuraEffectActiveGetAmount()
	{
		int num = 0;
		List<GameObject> currentActiveUnits = GetCurrentActiveUnits();
		for (int i = 0; i < currentActiveUnits.Count; i++)
		{
			if (currentActiveUnits[i] == null)
			{
				Debug.Log("----------------------currentActiveUnits[i] is null when it shouldnt------------------------");
			}
			else if (currentActiveUnits[i].GetComponent<UnitEffects>().IsHypersensitiveAuraEffectActive())
			{
				num++;
			}
		}
		return num;
	}

	public int IsDarknessAuraEffectActiveGetAmount()
	{
		int num = 0;
		List<GameObject> currentActiveUnits = GetCurrentActiveUnits();
		for (int i = 0; i < currentActiveUnits.Count; i++)
		{
			if (currentActiveUnits[i] == null)
			{
				Debug.Log("----------------------currentActiveUnits[i] is null when it shouldnt------------------------");
			}
			else
			{
				num += currentActiveUnits[i].GetComponent<UnitEffects>().IsDarknessAuraEffectActive();
			}
		}
		return num;
	}

	public GameObject IsUnitWithElectrostaticField(GameObject removeEffectOwnerGameObject = null)
	{
		List<GameObject> list = GetCurrentActiveUnits().Duplicate();
		if (removeEffectOwnerGameObject != null)
		{
			list.Remove(removeEffectOwnerGameObject);
		}
		for (int i = 0; i < list.Count; i++)
		{
			if (list[i].GetComponent<UnitEffects>().IsElectrostaticField())
			{
				return list[i];
			}
		}
		return null;
	}

	public bool EveryTargetHasIndigoRite(Effect indigoRite)
	{
		List<GameObject> currentActiveUnits = GetCurrentActiveUnits();
		bool flag = true;
		for (int i = 0; i < currentActiveUnits.Count; i++)
		{
			if (!currentActiveUnits[i].GetComponent<UnitEffects>().IsEffectActive(indigoRite, activateFeedback: false))
			{
				flag = false;
				break;
			}
		}
		if (flag)
		{
			for (int j = 0; j < currentActiveUnits.Count; j++)
			{
				currentActiveUnits[j].GetComponent<UnitEffects>().IsEffectActiveRemoveEffect(indigoRite);
			}
		}
		return flag;
	}

	public bool IsAnyTargetWithEffect(Effect effect)
	{
		List<GameObject> currentActiveUnits = GetCurrentActiveUnits();
		for (int i = 0; i < currentActiveUnits.Count; i++)
		{
			if (currentActiveUnits[i].GetComponent<UnitEffects>().IsEffectActive(effect, activateFeedback: false))
			{
				return true;
			}
		}
		return false;
	}

	public int TargetWithEffectAmount(Effect effect)
	{
		int num = 0;
		List<GameObject> currentActiveUnits = GetCurrentActiveUnits();
		for (int i = 0; i < currentActiveUnits.Count; i++)
		{
			if (currentActiveUnits[i].GetComponent<UnitEffects>().IsEffectActive(effect, activateFeedback: false))
			{
				num++;
			}
		}
		return num;
	}
}
